export type AdviceShareInvocation = { version: 1; scope: { shareId: string; guestId: string; epoch: number; }; action: { version: 1; kind: "map.tile"; dayKey: string; z: number; x: number; y: number; } | { version: 1; kind: "read"; commentsCursor?: string | undefined; } | { version: 1; kind: "vote.set"; requestId: string; placeKey: string; value: 0 | 1 | -1; expectedVersion: number; } | { version: 1; kind: "comment.create"; requestId: string; text: string; displayName?: string | undefined; } | { version: 1; kind: "comment.delete"; requestId: string; commentId: string; } | { version: 1; kind: "places.autocomplete"; searchId: string; cityId: string; category: "see" | "eat"; input: string; locale: string; } | { version: 1; kind: "places.resolve"; searchId: string; predictionId: string; } | { version: 1; kind: "suggestion.create"; requestId: string; selectionId: string; category: "see" | "eat"; reason?: string | undefined; displayName?: string | undefined; dayKey?: string | undefined; } | { version: 1; kind: "suggestion.withdraw"; requestId: string; suggestionId: string; } | { version: 1; kind: "session.erase"; requestId: string; } | { version: 1; kind: "places.metadata"; placeKey: string; } | { version: 1; kind: "suggestion.update"; requestId: string; suggestionId: string; category: "see" | "eat"; reason?: string | undefined; displayName?: string | undefined; selectionId?: string | undefined; dayKey?: string | undefined; }; };

export interface AdviceOwnerShareContext {
  getNative?(input: { tripId: number }): Promise<Omit<AdviceNativeOwnerResponse, 'inbox'>>;
  configureNative?(input: AdviceOwnerWriteV2 & { tripId: number }): Promise<Omit<AdviceNativeOwnerResponse, 'inbox'>>;
  previewNative?(input: { tripId: number; config: AdviceShareConfigV2 }): Promise<AdviceProjectionV2>;
  nativeAction?(input: { tripId: number; action: AdviceActionV2 }): Promise<{ providerResult: AdviceWriteResponseV2 } | { scope: AdviceShareInvocation['scope']; projection: AdviceProjectionV2 }>;
  resolveNativeSelection?(input: { tripId: number; selectionId: string }): Promise<AdviceResolvedSelection>;
  nativePhoto?(input: { tripId: number; handle: string }): Promise<AdvicePhotoResult>;
  cityAutocomplete?(input: AdviceOwnerCityAutocomplete): Promise<AdviceOwnerCityAutocompleteResult>;
  cityResolve?(input: AdviceOwnerCityResolve): Promise<{ city: AdviceAddedCity; owner: Omit<AdviceNativeOwnerResponse, 'inbox'> }>;
  getConfig(input: { tripId: number }): Promise<AdviceOwnerConfig | null>;
  getCandidates(input: { tripId: number }): Promise<AdviceOwnerCandidates>;
  preview(input: { tripId: number; config: AdviceShareConfig }): Promise<AdviceProjection>;
  configure(input: { tripId: number; expectedRevision: number; config: AdviceShareConfig;
    enabled: boolean; expiresInDays: number; previewRevision?: string }): Promise<AdviceOwnerConfig>;
  importSuggestion(input: AdviceNativeImport): Promise<AdviceNativeImportResult>;
}

export interface AdvicePublicShareContext {
  filterSuggestionKeys?(input: { keys: string[] }): Promise<string[]>;
  snapshot(): Promise<AdviceProjection>;
  resolveSelection(input: { selectionId: string }): Promise<AdviceResolvedSelection>;
  readonly owner: AdviceOwnerShareContext;
}
